CREATE TABLE IF NOT EXISTS task_extensions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,task_id CHAR(36) NOT NULL,actor_id CHAR(36) NOT NULL,minutes_added SMALLINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(task_id),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(160) NOT NULL,body VARCHAR(500) NOT NULL,href VARCHAR(255),is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS task_messages (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,sender_id CHAR(36) NOT NULL,recipient_id CHAR(36) NOT NULL,body VARCHAR(2000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(task_id,created_at),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(recipient_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reports (id CHAR(36) PRIMARY KEY,task_id CHAR(36),reporter_id CHAR(36) NOT NULL,reason VARCHAR(80) NOT NULL,details VARCHAR(1500) NOT NULL,status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at),FOREIGN KEY(reporter_id) REFERENCES users(id),FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE IF NOT EXISTS user_profiles (user_id CHAR(36) PRIMARY KEY,headline VARCHAR(120),bio VARCHAR(1500),skills JSON,location VARCHAR(100),updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
